-- Миграция: справочник норм для анализа волос (6 элементов), пол/возраст, дефицит/перенасыщение
-- Выполните после основной схемы. Референсы по данным пользователя (ИНВИТРО).

USE sngvkus;

CREATE TABLE IF NOT EXISTS hair_micro_norms (
    id INT AUTO_INCREMENT PRIMARY KEY,
    element_key VARCHAR(32) NOT NULL,
    element_label_ru VARCHAR(64) NOT NULL,
    sex ENUM('male', 'female') NOT NULL,
    age_min INT NOT NULL,
    age_max INT NOT NULL,
    ref_min DECIMAL(14, 6) NOT NULL,
    ref_max DECIMAL(14, 6) NOT NULL,
    unit VARCHAR(32) NOT NULL DEFAULT 'мкг/г',
    deficit_text TEXT NOT NULL,
    surplus_text TEXT NOT NULL,
    INDEX idx_lookup (element_key, sex, age_min, age_max)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS analysis_surplus (
    id INT AUTO_INCREMENT PRIMARY KEY,
    analysis_id INT NOT NULL,
    element_name VARCHAR(255) NOT NULL,
    FOREIGN KEY (analysis_id) REFERENCES analysis_data(id) ON DELETE CASCADE,
    INDEX idx_analysis (analysis_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE analysis_data
    ADD COLUMN subject_age INT NULL COMMENT 'Возраст на момент анализа' AFTER file_name,
    ADD COLUMN subject_sex ENUM('male', 'female') NULL COMMENT 'Пол' AFTER subject_age,
    ADD COLUMN subject_profile_key VARCHAR(32) NULL COMMENT 'Профиль пол+возрастная группа (например female_12_17)' AFTER subject_sex;

ALTER TABLE micro_elements
    ADD COLUMN ref_min DECIMAL(14, 6) NULL COMMENT 'Нижняя граница референса' AFTER norm,
    ADD COLUMN ref_max DECIMAL(14, 6) NULL COMMENT 'Верхняя граница референса' AFTER ref_min,
    ADD COLUMN balance_status ENUM('normal', 'deficit', 'surplus') NOT NULL DEFAULT 'normal' AFTER deficiency,
    ADD COLUMN consequence_text TEXT NULL COMMENT 'Последствия при текущем статусе' AFTER balance_status;

-- Очистка перед повторной заливкой (опционально; раскомментируйте при пересоздании справочника)
-- TRUNCATE TABLE hair_micro_norms;

